PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry tall_skinny_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr
)
{
    .reg .u32 %r<40>;
    .reg .u64 %rd<20>;
    .reg .f32 %f<10>;
    .reg .pred %p<5>;
    .shared .align 4 .b8 smA[2048];
    .shared .align 4 .b8 smB[2048];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    // Threadblock computes a 16x16 tile of C using a 16x32 tile of A
    // and a 32x16 tile of B staged through shared memory (K = 32 fully unrolled).
    mov.u32 %r1, %tid.x;      // tx (0..15)
    mov.u32 %r2, %tid.y;      // ty (0..15)
    mov.u32 %r3, %ctaid.x;    // bx
    mov.u32 %r4, %ctaid.y;    // by
    mov.u32 %r5, 16;          // TILE
    mad.lo.u32 %r6, %r3, %r5, %r1;   // col = bx*16 + tx
    mad.lo.u32 %r7, %r4, %r5, %r2;   // row = by*16 + ty
    mov.u32 %r8, 32;          // K
    // ---- Stage A tile: smA[ty*32 + k] = A[row*32 + k], k = tx and tx+16 ----
    mad.lo.u32 %r9, %r7, %r8, %r1;   // idxA1 = row*32 + tx
    mul.wide.u32 %rd4, %r9, 4;
    add.u64 %rd5, %rd1, %rd4;
    ld.global.f32 %f1, [%rd5];
    mad.lo.u32 %r10, %r2, %r8, %r1;  // sA1 = ty*32 + tx
    mul.lo.u32 %r11, %r10, 4;
    mov.u32 %r12, smA;
    add.u32 %r13, %r12, %r11;
    st.shared.f32 [%r13], %f1;
    add.u32 %r14, %r1, 16;           // tx+16
    mad.lo.u32 %r15, %r7, %r8, %r14; // idxA2 = row*32 + tx+16
    mul.wide.u32 %rd6, %r15, 4;
    add.u64 %rd7, %rd1, %rd6;
    ld.global.f32 %f2, [%rd7];
    add.u32 %r16, %r10, 16;          // sA2 = ty*32 + tx+16
    mul.lo.u32 %r17, %r16, 4;
    add.u32 %r18, %r12, %r17;
    st.shared.f32 [%r18], %f2;
    // ---- Stage B tile: smB[k*16 + tx] = B[k*32768 + col], k = ty and ty+16 ----
    mov.u32 %r19, 32768;             // N
    mad.lo.u32 %r20, %r2, %r19, %r6; // idxB1 = ty*32768 + col
    mul.wide.u32 %rd8, %r20, 4;
    add.u64 %rd9, %rd2, %rd8;
    ld.global.f32 %f3, [%rd9];
    mad.lo.u32 %r21, %r2, %r5, %r1;  // sB1 = ty*16 + tx
    mul.lo.u32 %r22, %r21, 4;
    mov.u32 %r23, smB;
    add.u32 %r24, %r23, %r22;
    st.shared.f32 [%r24], %f3;
    add.u32 %r25, %r2, 16;           // ty+16
    mad.lo.u32 %r26, %r25, %r19, %r6; // idxB2 = (ty+16)*32768 + col
    mul.wide.u32 %rd10, %r26, 4;
    add.u64 %rd11, %rd2, %rd10;
    ld.global.f32 %f4, [%rd11];
    mad.lo.u32 %r27, %r25, %r5, %r1; // sB2 = (ty+16)*16 + tx
    mul.lo.u32 %r28, %r27, 4;
    add.u32 %r29, %r23, %r28;
    st.shared.f32 [%r29], %f4;
    bar.sync 0;
    // ---- Compute dot-product over K=32 using shared-memory operands ----
    mov.f32 %f5, 0f00000000;
    mov.u32 %r30, 0;
    mul.lo.u32 %r31, %r2, %r8;       // rowBase = ty*32
LOOP:
    add.u32 %r32, %r31, %r30;        // ty*32 + k
    mul.lo.u32 %r33, %r32, 4;
    add.u32 %r34, %r12, %r33;
    ld.shared.f32 %f6, [%r34];
    mad.lo.u32 %r35, %r30, %r5, %r1; // k*16 + tx
    mul.lo.u32 %r36, %r35, 4;
    add.u32 %r37, %r23, %r36;
    ld.shared.f32 %f7, [%r37];
    fma.rn.f32 %f5, %f6, %f7, %f5;
    add.u32 %r30, %r30, 1;
    setp.lt.u32 %p1, %r30, 32;
    @%p1 bra LOOP;
    // C[row*32768 + col] = f5
    mad.lo.u32 %r38, %r7, %r19, %r6;
    mul.wide.u32 %rd12, %r38, 4;
    add.u64 %rd13, %rd3, %rd12;
    st.global.f32 [%rd13], %f5;
    ret;
